import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
class ClampTest {
    @Test void representativeAndBoundaryValues() {
        assertEquals(2, Clamp.clamp(-4, 2, 8));
        assertEquals(2, Clamp.clamp(2, 2, 8));
        assertEquals(5, Clamp.clamp(5, 2, 8));
        assertEquals(8, Clamp.clamp(8, 2, 8));
        assertEquals(8, Clamp.clamp(12, 2, 8));
    }
    @Test void degenerateInterval() {
        assertEquals(3, Clamp.clamp(-1, 3, 3));
        assertEquals(3, Clamp.clamp(3, 3, 3));
        assertEquals(3, Clamp.clamp(9, 3, 3));
    }
    @Test void rejectsReversedInterval() {
        assertThrows(IllegalArgumentException.class, () -> Clamp.clamp(5, 8, 2));
    }
}
